$('place-search').oninput=()=>{clearTimeout(searchTimer);searchSequence++;$('place-results').hidden=true;searchTimer=setTimeout(searchPlaces,250);};
$('place-search').onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();clearTimeout(searchTimer);searchPlaces();}if(e.key==='Escape'){$('place-results').hidden=true;searchSequence++;}};
$('place-clear').onclick=manualPlace;$('dst-choice').onchange=()=>{$('offset').value=$('dst-choice').value;};$('offset').oninput=()=>{manualZone=true;cityOffset();};
function now(){const zone=selectedPlace&&!manualZone?selectedPlace.timezone:null;const d=new Date();if(zone){const f=new Intl.DateTimeFormat('sv-SE',{timeZone:zone,year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).format(d);$('moment').value=f.replace(' ','T');cityOffset();}else $('moment').value=new Date(+d+Number($('offset').value)*3600000).toISOString().slice(0,16);}
$('now').onclick=now;$('moment').onchange=cityOffset;for(const id of ['lat','lon'])$(id).oninput=manualPlace;
function input(){if($('place-search').value.trim()&&$('place-search').value.trim()!==selectedPlace?.name)throw Error('Выберите населённый пункт из результатов поиска или нажмите «Вручную».');if(selectedPlace&&!manualZone){cityOffset();if(['missing','unsupported'].includes(localResolution?.status))throw Error($('zone-hint').textContent);}return {analysisVersion:2,topicMode:$('topic-mode').value,actorInput:$('actor-input').value,horizon:Number($('horizon').value),question:$('question').value,utc:new Date(new Date($('moment').value+'Z').getTime()-Number($('offset').value)*3600000).toISOString(),local:$('moment').value,offset:Number($('offset').value),city:$('city').value,place:selectedPlace?{...selectedPlace}:null,manualZone,lat:Number($('lat').value),lon:Number($('lon').value),system:$('system').value,target:Number($('target').value)};}
function restorePlace(i){selectedPlace=i.place||null;manualZone=i.manualZone??!selectedPlace;if(!selectedPlace&&cities[i.city]){const c=cities[i.city];selectedPlace={name:i.city,country:'',region:'',lat:c[0],lon:c[1],timezone:c[2]};manualZone=false;}$('place-search').value=selectedPlace?.name||'';$('place-selected').textContent=selectedPlace?placeLabel(selectedPlace):'Координаты вручную';$('place-results').hidden=true;searchSequence++;cityOffset();$('offset').value=i.offset;if(localResolution?.status==='ambiguous')$('dst-choice').value=String(i.offset);}
function formatLon(l){const total=Math.round(H.mod(l)*60)%21600,s=Math.floor(total/1800),d=Math.floor(total%1800/60),m=total%60;return `${d}°${String(m).padStart(2,'0')}′ ${H.signs[s]}`;}
